extension UIFont {
    static func dlBody(
        size: CGFloat,
        weight: UIFont.Weight = .regular
    ) -> UIFont {
        if let font = UIFont(name: "Netflix Sans", size: size) {
            let descriptor = font.fontDescriptor.addingAttributes([
                .traits: [
                    UIFontDescriptor.TraitKey.weight: weight.rawValue as NSNumber
                ]
            ])
            return UIFont(descriptor: descriptor, size: size)
        }
        return .systemFont(ofSize: size, weight: weight)
    }
    static func dlHeading(
        size: CGFloat,
        weight: UIFont.Weight = .regular
    ) -> UIFont {
        if let font = UIFont(name: "Netflix Sans", size: size) {
            let descriptor = font.fontDescriptor.addingAttributes([
                .traits: [
                    UIFontDescriptor.TraitKey.weight: weight.rawValue as NSNumber
                ]
            ])
            return UIFont(descriptor: descriptor, size: size)
        }
        return .systemFont(ofSize: size, weight: weight)
    }
}

